import math

def solve(
    times: list[float],
    frequency: float,
    amplitude: float,
    phase: float,
) -> list[float]:
    return sample_cosine(times,frequency,amplitude,phase)

def sample_cosine(times, frequency, amplitude, phase):
    return [amplitude*math.cos(2*math.pi*frequency*t+phase) for t in times]

p06-causal-average:
import math

def solve(
    values: list[float],
    window: int,
) -> list[float]:
    return causal_average(values,window)

def causal_average(values, window):
    return [sum(values[max(0,n-window+1):n+1])/min(n+1,window) for n in range(len(values))]

